// ============================================================
//  CONFIGURATION
// ============================================================
const CONFIG = {
  brand: 'Portefolia',
  tagline: 'Expose ton futur.',
  frontUrl: 'https://portefolia.tech',
  apiUrl: 'https://portefolia.tech/api',          // ou http://localhost:<port>/api si n8n tourne sur le même VPS
  fromEmail: 'Portefolia <support@portefolia.tech>', // doit être l'adresse du compte SMTP
  replyTo: 'support@portefolia.tech',
  adminEmail: 'diankaseydou52@gmail.com',             // reçoit toutes les notifications de la plateforme
  supportWhatsapp: '+221 78 131 13 71',
  colors: { primary: '#1B5E20', accent: '#2E7D32' },
};
return $input.all().map((i) => ({ json: { ...i.json, config: CONFIG } }));

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fcfa = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' F CFA';
const para = (html) => `<p style="font-size:15px;line-height:1.6;margin:0 0 12px">${html}</p>`;
const table = (rows) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="font-size:14px;border-top:1px solid #e5e7eb;border-bottom:1px solid #e5e7eb;margin:16px 0">${rows
  .filter((r) => r && r[1] !== undefined && r[1] !== null && r[1] !== '')
  .map(([k, v, raw]) => `<tr><td style="padding:7px 0;color:#6b7280;width:42%;vertical-align:top">${esc(k)}</td><td style="padding:7px 0;font-weight:600">${raw ? v : esc(v)}</td></tr>`).join('')}</table>`;
const dateFr = (d) => { if (!d) return ''; const x = new Date(d); return Number.isNaN(x.getTime()) ? String(d) : x.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' }); };

function layout(cfg, { preheader = '', title, body, cta, footer }) {
  const button = cta && cta.url
    ? `<p style="margin:28px 0 8px;text-align:center"><a href="${esc(cta.url)}" style="background:${cfg.colors.accent};color:#ffffff;text-decoration:none;padding:14px 26px;border-radius:8px;font-weight:600;display:inline-block">${esc(cta.label)}</a></p>`
    : '';
  return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title></head>
<body style="margin:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2937">
<span style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader)}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden">
<tr><td style="background:${cfg.colors.primary};padding:22px 28px;color:#ffffff;font-size:20px;font-weight:700">${esc(cfg.brand)}<div style="font-size:12px;font-weight:400;opacity:.85;margin-top:4px">${esc(cfg.tagline)}</div></td></tr>
<tr><td style="padding:28px">
<h1 style="font-size:20px;line-height:1.3;margin:0 0 16px">${esc(title)}</h1>
${body}
${button}
</td></tr>
<tr><td style="padding:18px 28px;background:#f9fafb;font-size:12px;line-height:1.5;color:#6b7280">${footer || 'Notification automatique de la plateforme Portefolia.'}</td></tr>
</table></td></tr></table></body></html>`;
}

// ---------- Une alerte par événement de la plateforme ----------
const out = [];
for (const item of $input.all()) {
  const cfg = item.json.config;
  const b = item.json.body || {};
  const L = b.links || {};
  let subject = null;
  let title = '';
  let body = '';
  let cta = null;
  let replyTo = cfg.replyTo;

  switch (b.event) {
    case 'user.registered': {
      const u = b.user || {};
      subject = `👤 Nouvelle inscription : ${u.name}`;
      title = 'Nouveau compte sur Portefolia';
      body = table([['Nom', u.name], ['E-mail', u.email], ['Téléphone', u.phone], ['Origine', u.source], ['Entreprise', u.company], ['E-mail vérifié', u.verified ? 'oui' : 'pas encore']])
        + (b.stats && b.stats.total_users ? para(`La plateforme compte maintenant <strong>${esc(b.stats.total_users)}</strong> comptes.`) : '');
      cta = { label: 'Voir le compte', url: L.admin_url };
      break;
    }
    case 'business.created': {
      const x = b.business || {};
      subject = `🏢 Nouveau compte Business : ${x.company}`;
      title = 'Nouveau compte Business';
      body = table([['Entreprise', x.company], ['Administrateur', x.admin_name], ['E-mail', x.email], ['Téléphone', x.phone], ['Formule', x.plan], ['Membres max', x.max_members]]);
      cta = { label: 'Voir les clients', url: L.admin_url };
      break;
    }
    case 'payment.submitted': {
      const p = b.payment || {}; const c = p.customer || {};
      subject = `⏳ Paiement Wave à valider : ${fcfa(p.amount)} — ${c.name}`;
      title = 'Paiement Wave à vérifier';
      body = para('Un client a déclaré un paiement Wave. Vérifiez la transaction dans Wave Business, puis validez-la dans l\'admin.')
        + table([['Client', c.name], ['E-mail', c.email], ['Formule', p.plan], ['Durée', p.months ? `${p.months} mois` : ''], ['Montant', fcfa(p.amount)], ['Référence Wave', p.reference],
          ['Preuve', p.proof_url ? `<a href="${esc(p.proof_url)}">voir la capture</a>` : '', true]]);
      cta = { label: 'Valider le paiement', url: L.admin_url };
      break;
    }
    case 'payment.succeeded':
    case 'payment.rejected':
    case 'payment.refunded': {
      const p = b.payment || {}; const c = p.customer || {};
      const kind = b.event.split('.')[1];
      const icon = { succeeded: '💰', rejected: '❌', refunded: '↩️' }[kind];
      const label = { succeeded: 'Paiement reçu', rejected: 'Paiement refusé', refunded: 'Paiement remboursé' }[kind];
      subject = `${icon} ${label} : ${fcfa(p.amount)} — ${p.type}${c.name && c.name !== '—' ? ` (${c.name})` : ''}`;
      title = label;
      body = table([['Montant', fcfa(p.amount)], ['Type', p.type], ['Formule', p.plan], ['Commande', p.order], ['Client', c.name], ['E-mail', c.email], ['Moyen', p.method], ['Référence', p.reference]]);
      cta = { label: 'Voir les paiements', url: L.admin_url };
      break;
    }
    case 'upgrade.requested': {
      const g = b.upgrade || {};
      subject = `⬆️ Changement de formule demandé : ${g.from || '?'} → ${g.to || '?'} (${g.name})`;
      title = 'Demande de changement de formule';
      body = table([['Client', g.name], ['E-mail', g.email], ['Formule actuelle', g.from], ['Nouvelle formule', g.to], ['Montant', g.amount ? fcfa(g.amount) : ''], ['Durée', g.months ? `${g.months} mois` : '']]);
      cta = { label: 'Voir les demandes', url: L.admin_url };
      break;
    }
    case 'subscription.expired': {
      const s = b.subscription || {}; const c = s.customer || {};
      subject = `⌛ Abonnement expiré : ${c.name}${s.plan ? ` (${s.plan})` : ''}`;
      title = 'Abonnement expiré';
      body = table([['Client', c.name], ['E-mail', c.email], ['Formule', s.plan], ['Expiré le', dateFr(s.expired_on)]])
        + para('Le client reçoit automatiquement les relances de renouvellement (J+3, J+10, J+30, J+60).');
      cta = { label: 'Voir le compte', url: L.admin_url };
      break;
    }
    case 'contact.message': {
      const m = b.contact || {};
      subject = `✉️ Message de contact : ${m.subject || 'sans objet'} (${m.name})`;
      title = 'Nouveau message du formulaire de contact';
      body = table([['De', m.name], ['E-mail', m.email], ['Objet', m.subject]])
        + `<div style="font-size:14px;line-height:1.6;background:#f9fafb;border-radius:8px;padding:14px;white-space:pre-wrap">${esc(m.message)}</div>`
        + para('<span style="color:#6b7280;font-size:13px">Répondez directement à cet e-mail : la réponse part chez l\'expéditeur.</span>');
      if (m.email) replyTo = m.email;
      cta = { label: 'Voir les messages', url: L.admin_url };
      break;
    }
    default:
      continue; // événement inconnu : rien à envoyer
  }

  out.push({ json: {
    event: b.event,
    to: cfg.adminEmail,
    from: cfg.fromEmail,
    replyTo,
    subject,
    html: layout(cfg, { preheader: subject, title, body, cta }),
  } });
}
return out;
